#!/bin/sh
#
# Output naming: the default flow filename template must name both
# connections deterministically, and a custom -T template (including the
# %H HTTP/2 stream token) must be honored. The pcap is generated by
# gen_test_pcaps.py.
#

. $srcdir/test-subs.sh

DMPFILE=$DMPDIR/naming-template.pcap

[ -r "$DMPFILE" ] || { echo "$DMPFILE not found" ; exit 77 ; }

OUT=out-naming

rm -rf $OUT

# 1. Default template names files src.sport-dst.dport.
cmd "$TCPFLOW -o $OUT -r $DMPFILE"

F1=$OUT/172.016.000.001.41001-172.016.000.002.07001
F2=$OUT/172.016.000.001.41002-172.016.000.002.07002

for f in "$F1" "$F2" ; do
  if [ ! -r "$f" ] ; then
    echo "failure: expected flow file $f"
    ls "$OUT"
    exit 1
  fi
done

if [ "`cat "$F1"`" != "naming-connection-one" ] ; then
  echo "failure: content mismatch in $F1"
  exit 1
fi
if [ "`cat "$F2"`" != "naming-connection-two" ] ; then
  echo "failure: content mismatch in $F2"
  exit 1
fi

rm -rf $OUT

# 2. Custom template with sub-directory and the %H token. Non-HTTP/2
#    flows must render %H as h2-000.
cmd "$TCPFLOW -T conns/%A.%a-%B.%b-%H -o $OUT -r $DMPFILE"

T1=$OUT/conns/172.016.000.001.41001-172.016.000.002.07001-h2-000
T2=$OUT/conns/172.016.000.001.41002-172.016.000.002.07002-h2-000

for f in "$T1" "$T2" ; do
  if [ ! -r "$f" ] ; then
    echo "failure: expected templated flow file $f"
    find "$OUT" -type f
    exit 1
  fi
done

if [ "`cat "$T1"`" != "naming-connection-one" ] ; then
  echo "failure: templated content mismatch in $T1"
  exit 1
fi
if [ "`cat "$T2"`" != "naming-connection-two" ] ; then
  echo "failure: templated content mismatch in $T2"
  exit 1
fi

rm -rf $OUT
exit 0
